// M5's "Done when": every record the store writes can be decoded and re-encoded
// byte-identically. That is the whole claim behind a recoverable history — a reader
// that cannot reproduce the bytes it read cannot tell corruption from a format change,
// and a restore built on either is a guess.
//
// The corpus is hand-written, one entry per operation, because a corpus generated by
// the encoder would only prove that the encoder is stable. The trees are hand-written
// too: sorted on the way in, so an implementation that preserved arrival order fails
// here rather than in a user's restore.

use crate::helpers::fresh_dir;
use el::adapters::fs_local::Local;
use el::core::history::entry::{Entry, Op};
use el::core::history::object::{self, Digest};
use el::core::history::tree::Tree;
use el::ports::Fs;
use std::fs;

fn digest(seed: u8) -> Digest {
    object::of(&[seed])
}

/// One entry for every operation the journal can record, with text that has to be
/// sanitized where it is free-form.
fn corpus() -> Vec<Entry> {
    Op::ALL
        .iter()
        .enumerate()
        .map(|(index, op)| Entry {
            seq: index as u64 + 1,
            ts: 1_767_225_600 + index as i64,
            actor: match index % 3 {
                0 => "human".to_string(),
                1 => "agent".to_string(),
                _ => "orbit\tworker".to_string(),
            },
            op: *op,
            target: match op {
                Op::Init | Op::Import | Op::Repair => "-".to_string(),
                Op::Policy => "el.policy".to_string(),
                _ => format!("el-{:04}", 7 + index),
            },
            from: digest(index as u8),
            to: digest(index as u8 + 100),
            gate: [
                "ok:new",
                "ok:fixed",
                "ok:existing",
                "rejected:3",
                "preview:1",
                "skip",
            ][index % 6]
                .to_string(),
            msg: format!("{} on el-{:04}\nstep {}", op.as_str(), 7 + index, index),
        })
        .collect()
}

/// The journal the store would hold: one file per sequence number.
fn write_journal(store: &Local, entries: &[Entry]) {
    for entry in entries {
        store
            .write(
                &format!("journal/{:06}", entry.seq),
                entry.encode().as_bytes(),
            )
            .expect("append entry");
    }
}

#[test]
fn every_recorded_entry_decodes_and_re_encodes_byte_identically() {
    let store = Local::new(fresh_dir("store-round-trip/entries"));
    let written = corpus();

    write_journal(&store, &written);
    let paths = store.list("journal").expect("list journal");

    assert_eq!(paths.len(), written.len());
    for path in paths {
        let on_disk = store.read(&path).expect("read").expect("present");
        let text = String::from_utf8(on_disk.clone()).expect("entries are text");

        let decoded = Entry::decode(&text).unwrap_or_else(|error| panic!("{path}: {error}"));
        assert_eq!(
            decoded.encode().as_bytes(),
            on_disk,
            "{path} does not re-encode"
        );
    }
}

#[test]
fn every_written_tree_decodes_and_re_encodes_byte_identically() {
    let store = Local::new(fresh_dir("store-round-trip/trees"));
    let tree = Tree::new(vec![
        ("src/lib.rs".to_string(), digest(1)),
        ("src/main.rs".to_string(), digest(2)),
        ("Cargo.toml".to_string(), digest(3)),
    ])
    .expect("distinct paths");
    let blob = tree.encode();

    store
        .write(&object::path(&digest(9)), blob.as_bytes())
        .expect("write");
    let read_back = store
        .read(&object::path(&digest(9)))
        .expect("read")
        .expect("present");

    assert_eq!(
        Tree::decode(&String::from_utf8(read_back).expect("text")).expect("decodes"),
        tree
    );
    assert_eq!(tree.encode().as_bytes(), blob.as_bytes());
}

#[test]
fn the_same_bytes_stored_twice_occupy_one_path() {
    let store = Local::new(fresh_dir("store-round-trip/dedupe"));

    for _ in 0..3 {
        let bytes = b"pub fn clamp(self, max: usize) -> Self { self }\n";
        store
            .write(&object::path(&object::of(bytes)), bytes)
            .expect("write");
    }

    assert_eq!(store.list("objects").expect("list").len(), 1);
}

#[test]
fn listing_a_store_that_was_never_written_is_empty_and_not_an_error() {
    let store = Local::new(fresh_dir("store-round-trip/empty"));

    assert_eq!(store.list("objects").expect("list"), Vec::<String>::new());
    assert_eq!(store.read("objects/ab/cdef").expect("read"), None);
    assert!(!store.exists("objects/ab/cdef").expect("exists"));
    assert_eq!(
        store.remove("objects/ab/cdef"),
        Ok(()),
        "absent is already removed"
    );
}

#[test]
fn a_store_written_in_two_runs_lists_the_same_way_each_time() {
    let root = fresh_dir("store-round-trip/determinism");
    let bytes: [&[u8]; 3] = [b"one", b"two", b"three"];

    for blob in bytes {
        Local::new(&root)
            .write(&object::path(&object::of(blob)), blob)
            .expect("write");
    }

    let first = Local::new(&root).list("objects").expect("list");
    let second = Local::new(&root).list("objects").expect("list");

    assert_eq!(first, second);
    assert_eq!(first.len(), 3);
    assert!(first.windows(2).all(|pair| pair[0] < pair[1]), "{first:?}");
}

#[test]
fn staging_files_are_never_listed_as_store_content() {
    let root = fresh_dir("store-round-trip/staging");
    let store = Local::new(&root);
    store.write("head", b"42\n").expect("write");
    fs::create_dir_all(root.join("tmp")).expect("mkdir tmp");
    fs::write(root.join("tmp/head.0.0.tmp"), b"99\n").expect("leftover");

    assert_eq!(store.list("").expect("list"), vec!["head".to_string()]);
    assert_eq!(
        store.read("head").expect("read").as_deref(),
        Some(&b"42\n"[..])
    );
}
